#!/usr/bin/env node
// =============================================================================
// QORVYNA — make sure the generated Android project is ready to build an APK.
//
// `src-tauri/gen/android` is generated by `tauri android init` and gitignored,
// so it may simply not exist yet. This script is the small, idempotent bridge
// every easy APK build (`npm run android:apk`, the GitHub Actions workflow)
// runs before invoking the Tauri CLI:
//
//   1. if `src-tauri/gen/android` is missing, run `tauri android init`;
//   2. re-apply `scripts/native/patch-android-manifest.mjs` (idempotent) so
//      the checked-in Kotlin sources (assistant bubble service, assistant
//      plugin, notification listener) are copied into the generated app module
//      and the manifest declares them.
//
// Without step 2 an APK still builds, but it silently ships WITHOUT the
// assistant/wake-word/notification services — which is exactly the mistake
// this script exists to prevent.
//
// Usage: node scripts/native/ensure-android-project.mjs
// =============================================================================
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const genAndroid = join(root, "src-tauri", "gen", "android");

function run(command, args) {
  execFileSync(command, args, {
    stdio: "inherit",
    cwd: root,
    // `npx`/`tauri` are .cmd shims on Windows; plain execFileSync cannot spawn
    // them there without a shell.
    shell: process.platform === "win32",
  });
}

if (!existsSync(join(genAndroid, "app"))) {
  console.log("[android] src-tauri/gen/android is missing — running `tauri android init` once.");
  run("npx", ["tauri", "android", "init"]);
} else {
  console.log("[android] generated Android project already present.");
}

console.log("[android] re-applying the manifest/Kotlin patch (idempotent).");
run("node", ["scripts/native/patch-android-manifest.mjs"]);

// Brand the launcher icon: `tauri icon` writes the QORVYNA mipmaps straight
// into the generated project's res/ folders (and refreshes src-tauri/icons).
// Without this, `tauri android init` ships Tauri's own default launcher icon.
console.log("[android] generating the branded launcher icons (tauri icon).");
run("npx", ["tauri", "icon", "src-tauri/icons/icon.png"]);

// App signing: when signing/keystore.properties exists (CI prepares it;
// a local build may provide its own), copy it into the generated project root
// where the patched Gradle build reads it. Without it the Gradle build falls
// back to the committed signing/qorvyna-upload.jks — so debug AND release APKs
// are always signed with the same key and install over / update each other
// instead of failing with "package conflicts with an existing package".
const keystoreProps = join(root, "signing", "keystore.properties");
if (existsSync(keystoreProps)) {
  const target = join(genAndroid, "keystore.properties");
  writeFileSync(target, readFileSync(keystoreProps, "utf8"));
  console.log("[android] app signing: keystore.properties placed in the generated project.");
} else {
  console.log("[android] app signing: no signing/keystore.properties — debug + release builds use the committed signing/qorvyna-upload.jks.");
}
